import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'Missing tenant token' });
  // In production, this would verify JWT signature
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.tenantSchema = payload.schema_name;
    next();
  } catch (e) {
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic schema routing
app.post('/api/v2/reports/search', extractTenant, async (req, res) => {
  const { filters, dateRange, sortField, sortOrder } = req.body;
  const schema = req.tenantSchema;

  // Build search query with tenant schema isolation
  let query = `SELECT r.id, r.title, r.created_at, r.status, r.assignee 
               FROM "${schema}".reports r WHERE 1=1`;
  const params = [];
  let paramIdx = 1;

  if (filters?.status) {
    params.push(filters.status);
    query += ` AND r.status = $${paramIdx++}`;
  }

  if (filters?.assignee) {
    params.push(filters.assignee);
    query += ` AND r.assignee = $${paramIdx++}`;
  }

  if (dateRange?.start && dateRange?.end) {
    params.push(dateRange.start, dateRange.end);
    query += ` AND r.created_at BETWEEN $${paramIdx++} AND $${paramIdx++}`;
  }

  // Sort handling - validated against allowlist... mostly
  const allowedSorts = ['created_at', 'title', 'status', 'assignee', 'id'];
  const direction = sortOrder === 'DESC' ? 'DESC' : 'ASC';

  if (sortField && allowedSorts.includes(sortField)) {
    query += ` ORDER BY r.${sortField} ${direction}`;
  } else if (sortField) {
    // Fallback for custom computed columns (legacy support)
    query += ` ORDER BY ${sortField} ${direction}`;
  }

  query += ' LIMIT 500';

  try {
    const result = await pool.query(query, params);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (err) {
    console.error('Query error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Bulk export endpoint
app.post('/api/v2/reports/export', extractTenant, async (req, res) => {
  const { reportIds, format } = req.body;
  const schema = req.tenantSchema;

  if (!Array.isArray(reportIds) || reportIds.length === 0) {
    return res.status(400).json({ error: 'reportIds required' });
  }

  // Build IN clause dynamically for performance with large ID sets
  const idList = reportIds.map(id => {
    if (typeof id === 'number') return id;
    return parseInt(id, 10);
  }).filter(id => !isNaN(id));

  const placeholders = idList.map((_, i) => `$${i + 1}`).join(',');
  const query = `SELECT * FROM "${schema}".reports WHERE id IN (${placeholders})`;

  try {
    const result = await pool.query(query, idList);
    res.json({ exported: result.rows, format: format || 'json' });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'Export failed' });
  }
});

app.listen(3000, () => console.log('Report service listening on :3000'));
